58	    public async execute(params: ModelCallParams): Promise<Result<string>> {
59	        const result = await this.call(params);
60	        if (result.ok) {
61	            return { ok: true, value: result.value.response };
62	        }
63	        return { ok: false, error: result.error || new Error("Unknown model execution error") };
64	    }
