66	    constructor(
67	        public readonly config: SovereignConfig,
68	        private readonly router?: TernaryRouter
69	    ) {
70	        this.trainingCollector = TrainingCollector.getInstance();
71	        this.digest = new ArchitectureDigest(process.cwd());
72	        // Fallback to router's hexagram if available
73	        const hex = router?.getHexagram() || (globalThis as any).hexagram;
74	        this.healer = new EndpointHealer(hex, this.trainingCollector);
75	
76	        // Massive local contexts (33b+) may take over 5 mins to load into VRAM or stream.
77	        // Node's default fetch relies on Undici which enforces a strict 300_000ms headers timeout.
78	        // We override this to 24 hours (86,400,000ms) for high-fidelity local perseverance until complete.
79	        this.customAgent = new Agent({
80	            headersTimeout: 86_400_000,
81	            bodyTimeout: 86_400_000,
82	            connectTimeout: 120_000
83	        });
84	    }
