106	    /** Check if the Ollama substrate is online */
107	    async checkHealth(): Promise<{ online: boolean; version: string }> {
108	        for (let attempt = 1; attempt <= 3; attempt++) {
109	            try {
110	                const resp = await undiciFetch(`${this.config.ollamaBaseUrl}/api/version`, {
111	                    signal: AbortSignal.timeout(15000)
112	                });
113	                if (resp.ok) {
114	                    const data = await resp.json() as { version?: string };
115	                    return { online: true, version: data.version || 'unknown' };
116	                }
117	            } catch {
118	                if (attempt === 3) return { online: false, version: 'unreachable' };
119	                await new Promise(res => setTimeout(res, 2000 * attempt));
120	            }
121	        }
122	        return { online: false, version: 'offline' };
123	    }
