126	    async listModels(): Promise<string[]> {
127	        for (let attempt = 1; attempt <= 3; attempt++) {
128	            try {
129	                const resp = await undiciFetch(`${this.config.ollamaBaseUrl}/api/tags`, {
130	                    signal: AbortSignal.timeout(15000)
131	                });
