156	    async call(params: ModelCallParams): Promise<Result<ModelResponse>> {
157	        const startTime = Date.now();
158	        let provider: 'ollama' | 'huggingface' | 'gemini' | 'cloudflare' | 'fireworks' | 'openrouter' | 'unknown' = 'ollama';
159	
160	        // Inject sovereign architectural constraints into all prompts
161	        const enforcedParams = {
162	            ...params,
163	            prompt: this.digest.inject(params.prompt)
164	        };
165	
166	        let result: Result<ModelResponse>;
167	
168	        const detectProvider = (model: string): string => {
169	            if (model.startsWith('gemini:')) return 'gemini';
170	            if (model.startsWith('huggingface:')) return 'huggingface';
171	            if (model.startsWith('fireworks:')) return 'fireworks';
172	            if (model.startsWith('openrouter:')) return 'openrouter';
173	            if (model.startsWith('@cf/') || model.includes('cloudflare')) return 'cloudflare';
174	            return 'ollama';
175	        };
176	
177	        provider = detectProvider(enforcedParams.model) as any;
178	        const priority = TaskScheduler.mapPriority(enforcedParams.yaoState || (globalThis as any).yaoState || YaoState.YoungYang);
179	        const timeout = this.getTimeoutByYaoState(enforcedParams.yaoState);
180	
181	        result = await TaskScheduler.getInstance().schedule(
182	            provider,
183	            priority,
184	            async () => {
185	                if (provider === 'gemini') {
186	                    return await this.callGemini(enforcedParams, startTime);
187	                } else if (provider === 'huggingface') {
188	                    return await this.callHuggingFace(enforcedParams, startTime);
189	                } else if (provider === 'fireworks') {
190	                    return await this.callFireworks(enforcedParams, startTime);
191	                } else if (provider === 'openrouter') {
192	                    return await this.callOpenRouter(enforcedParams, startTime);
193	                } else if (provider === 'cloudflare') {
194	                    return await this.callCloudflare(enforcedParams, startTime);
195	                } else {
196	                    return await this.callOllama(enforcedParams, startTime);
197	                }
198	            },
199	            timeout
200	        );
201	
202	        // Record interaction to D:\ training substrate (Skip for System Pulse)
203	        const latency = Date.now() - startTime;
204	        if (!enforcedParams.isSystemPulse) {
205	            this.trainingCollector.recordInteraction({
206	                model: enforcedParams.model,
207	                provider,
208	                category: enforcedParams.category as any,
209	                prompt: enforcedParams.prompt.substring(0, 2000),
210	                response: result.ok ? result.value.response.substring(0, 2000) : '',
211	                latencyMs: latency,
212	                tokenCount: result.ok ? result.value.tokensUsed : undefined,
213	                success: result.ok,
214	                error: result.ok ? undefined : result.error?.message
215	            }).catch(() => { /* non-blocking */ });
216	
217	            this.trainingCollector.recordMetric({
218	                model: enforcedParams.model,
219	                provider,
220	                latencyMs: latency,
221	                success: result.ok,
222	                tokenCount: result.ok ? result.value.tokensUsed : undefined
223	            }).catch(() => { /* non-blocking */ });
224	        }
225	
226	        // Phase 6: Update ModelRolodex with call metrics (Skip for System Pulse)
227	        if (this.rolodex && !enforcedParams.isSystemPulse) {
228	            this.rolodex.recordCallResult(
229	                enforcedParams.model,
230	                ModelRolodex.toRolodexProvider(provider),
231	                result.ok,
232	                latency,
233	                result.ok ? result.value.tokensUsed : undefined
234	            );
235	        }
236	
237	        // Sovereign FinOps: Record quota usage
238	        if (this.quotaTracker) {
239	            const quotaProvider = provider as QuotaProvider;
240	            const tokensUsed = result.ok ? (result.value.tokensUsed ?? 0) : 0;            this.quotaTracker.recordUsage(quotaProvider, tokensUsed, 1);
241	        }
242	
243	        return result;
244	    }
