246	    private getTimeoutByYaoState(yaoState?: YaoState): number {
247	        if (yaoState === undefined && (globalThis as any).yaoState !== undefined) {
248	            yaoState = (globalThis as any).yaoState;
249	        }
250	        if (yaoState === undefined) return 300_000; // Default 5 mins
251	
252	        switch (yaoState) {
253	            case YaoState.OldYang:   // 3: Deep metamorphic change
254	            case YaoState.OldMixed:  // 4: Chaotic complexity
255	                return 86_400_000;   // 24 hours for deep sovereignty
256	            case YaoState.YoungYin:
257	                return 180_000; // 3m fast response
258	            case YaoState.YoungYang: // 2: Stable expansion
259	            case YaoState.OldYin:    // 1: Structural break
260	                return 3_600_000;    // 1 hour
261	            case YaoState.YoungMixed:// 5: Emerging
262	                return 600_000;     // 10 mins
263	            default:
264	                return 300_000;
265	        }
266	    }
