268	    /**
269	     * Resilient Call: Automatically retries with a fallback model from the router if the first attempt fails.
270	     */
271	    async resilientCall(params: ModelCallParams & { maxRetries?: number }): Promise<Result<ModelResponse>> {
272	        let attempts = 0;
273	        const maxRetries = params.maxRetries ?? 2;
274	        let lastError: Error | undefined;
275	        let cascadeIndex = -1;
276	        let failoverSequence: string[] = [];
277	
278	        while (attempts <= maxRetries) {
279	            const result = await this.call(params);
280	            if (result.ok) return result;
281	
282	            lastError = result.error;
283	            attempts++;
284	
285	            if (attempts <= maxRetries && this.router) {
286	                logger.warn({ model: params.model, attempt: attempts }, 'Model call failed, seeking fallback...');
287	                this.router.recordFailure(params.model);
288	
289	                // Phase 2: If a tier is explicitly provided, use the tier's failover sequence directly
290	                if (params.tier) {
291	                    if (failoverSequence.length === 0) {
292	                        failoverSequence = Array.from(new Set(this.router.getFailoverSequence(params.tier)));
293	                        cascadeIndex = failoverSequence.indexOf(params.model);
294	                        if (cascadeIndex === -1) cascadeIndex = 0;
295	                    }
296	                    if (cascadeIndex < failoverSequence.length - 1) {
297	                        cascadeIndex++;
298	                        params = { ...params, model: failoverSequence[cascadeIndex] };
299	                        logger.info({ nextModel: params.model, tier: params.tier }, 'Tier-aware cascade to next substrate');
300	                    } else {
301	                        logger.error({ tier: params.tier }, 'All substrates in tier exhausted');
302	                        break;
303	                    }
304	                } else {
305	                    // Legacy Phase 72/76.3 logic: Deduplicate sequence and advance index explicitly
306	                    if (failoverSequence.length === 0) {
307	                        const currentComplexity = await this.router.classify(params.prompt);
308	                        const isMaster = params.model === this.config.masterReasoningModel || params.model === this.config.masterFallbackModel || params.model === this.config.masterLocalModel || params.model === this.config.orchestratorModel;
309	
310	                        const decision = await this.router.route(isMaster ? 'Orchestrator' : currentComplexity);
311	                        failoverSequence = Array.from(new Set(this.router.getFailoverSequence(decision.tier)));
312	                        cascadeIndex = failoverSequence.indexOf(params.model);
313	                    }
314	
315	                    if (cascadeIndex !== -1 && cascadeIndex < failoverSequence.length - 1) {
316	                        cascadeIndex++;
317	                        params = { ...params, model: failoverSequence[cascadeIndex] };
318	                        logger.info({ nextModel: params.model }, 'Cascading to next model in sequence');
319	                    } else {
320	                        // Fallback to standard routing if not in sequence or at end
321	                        const currentComplexity = await this.router.classify(params.prompt);
322	                        const newRoute = await this.router.route(currentComplexity);
323	                        if (newRoute.model === params.model) break;
324	                        params = { ...params, model: newRoute.model };
325	                    }
326	                }
327	            }
328	        }
329	
330	        // All retries exhausted Ã¢â‚¬â€ invoke EndpointHealer before final failure
331	        const provider: 'ollama' | 'huggingface' | 'gemini' | 'cloudflare' | 'fireworks' | 'openrouter' | 'unknown' = params.model.startsWith('gemini:') ? 'gemini'
332	            : params.model.startsWith('huggingface:') ? 'huggingface'
333	                : params.model.startsWith('fireworks:') ? 'fireworks'
334	                    : params.model.startsWith('openrouter:') ? 'openrouter'
335	                        : params.model.startsWith('@cf/') || params.model.includes('cloudflare') ? 'cloudflare'
336	                            : 'ollama';
337	        const diagnostic = await this.healer.diagnoseAndHeal(provider, lastError?.message || 'Unknown', params.model);
338	
339	        if (diagnostic.resolved) {
340	            // One final attempt after healing
341	            logger.info({ resolution: diagnostic.resolution }, 'EndpointHealer resolved issue Ã¢â‚¬â€ retrying...');
342	            const finalAttempt = await this.call(params);
343	
344	            // Phase 56: Persistent Training Loop - Record Error Fix
345	            this.trainingCollector.recordErrorFix({
346	                errorMessage: lastError?.message || 'Unknown',
347	                resolution: diagnostic.resolution,
348	                model: params.model,
349	                success: finalAttempt.ok
350	            }).catch(() => { /* Non-blocking training persistence */ });
351	
352	            if (finalAttempt.ok) return finalAttempt;
353	        }
354	
355	        return { ok: false, error: lastError || new Error('Max retries exceeded Ã¢â‚¬â€ EndpointHealer could not resolve') };
356	    }
