358	    async embed(text: string, modelOverride?: string): Promise<Result<Float32Array>> {
359	        const model = modelOverride || this.config.embeddingModel || 'qwen3-embedding:latest';
360	
361	        let result: Result<Float32Array>;
362	        if (model && model.startsWith('gemini:')) {
363	            result = await this.embedGemini(text);
364	        } else {
365	            result = await this.embedOllama(text, model);
366	            
367	            // Phase 108/114: Real Resilient Embedding Fallback
368	            if (!result.ok && this.config.secondaryCloudApiKey) {
369	                logger.warn({ model, error: result.error?.message }, 'Primary local embedding failed. Attempting Gemini fallback substrate...');
370	                const geminiFallback = await this.embedGemini(text);
371	                if (geminiFallback.ok) {
372	                    logger.info('Gemini embedding fallback successful.');
373	                    return geminiFallback;
374	                } else {
375	                    logger.error({ error: geminiFallback.error?.message }, 'Gemini embedding fallback also failed (Quota exhausted or network down).');
376	                }
377	            } else if (!result.ok) {
378	                 logger.error({ model, error: result.error?.message }, 'Primary local embedding failed. Gemini fallback disabled (No API Key).');
379	            }
380	        }
381	
382	        return result;
383	    }
