385	    private async callGemini(params: ModelCallParams, startTime: number): Promise<Result<ModelResponse>> {
386	        const apiKey = this.config.secondaryCloudApiKey;
387	        if (!apiKey) {
388	            return { ok: false, error: new Error('SECONDARY_CLOUD_API_KEY not set Ã¢â‚¬â€ cannot call cloud substrate') };
389	        }
390	
391	        // Tiered Gemini Fallback Sequence
392	        const primaryModelId = params.model.replace('gemini:', '');
393	        const fallbackSequence = [
394	            primaryModelId,
395	            this.config.geminiFlashModel,
396	            'gemini-1.5-flash-001',
397	            this.config.geminiProModel
398	        ];
399	
400	        // Deduplicate
401	        const uniqueSequence = Array.from(new Set(fallbackSequence));
402	        let lastError: Error | undefined;
403	
404	        for (const modelId of uniqueSequence) {
405	            const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelId}:generateContent?key=${apiKey}`;
406	
407	            const messages: Array<{ role: string; parts: Array<{ text: string }> }> = [];
408	
409	            if (params.systemPrompt) {
410	                messages.push({ role: 'user', parts: [{ text: params.systemPrompt }] });
411	                messages.push({ role: 'model', parts: [{ text: 'Understood.' }] });
412	            }
413	
414	            messages.push({ role: 'user', parts: [{ text: params.prompt }] });
415	
416	            const body = {
417	                contents: messages,
418	                generationConfig: {
419	                    temperature: params.temperature ?? 0.3,
420	                    maxOutputTokens: params.maxTokens ?? 8192
421	                }
422	            };
423	
424	            try {
425	                let response = await undiciFetch(url, {
426	                    method: 'POST',
427	                    headers: { 'Content-Type': 'application/json' },
428	                    body: JSON.stringify(body),
429	                    signal: AbortSignal.timeout(this.getTimeoutByYaoState(params.yaoState))
430	                });
431	
432	                if (!response.ok) {
433	                    const errorText = await response.text();
434	
435	                    // If 404, try next model in sequence
436	                    if (response.status === 404) {
437	                        logger.warn({ modelId, status: 404 }, 'Gemini model not found (404), trying next in sequence...');
438	                        lastError = new Error(`Gemini model ${modelId} not found: ${errorText}`);
439	                        continue;
440	                    }
441	
442	                    logger.warn({ status: response.status, errorText }, 'Secondary Cloud API failed. Attempting substrate-specific CLI fallback...');
443	
444	                    try {
445	                        const { stdout } = await execAsync('gcloud auth print-access-token');
446	                        const token = stdout.trim();
447	                        if (token) {
448	                            const fallbackUrl = `https://generativelanguage.googleapis.com/v1beta/models/${modelId}:generateContent`;
449	                            response = await undiciFetch(fallbackUrl, {
450	                                method: 'POST',
451	                                headers: {
452	                                    'Content-Type': 'application/json',
453	                                    'Authorization': `Bearer ${token}`
454	                                },
455	                                body: JSON.stringify(body),
456	                                signal: AbortSignal.timeout(this.getTimeoutByYaoState(params.yaoState))
457	                            });
458	
459	                            if (!response.ok) {
460	                                const fallbackErrorText = await response.text();
461	                                lastError = new Error(`Gemini API & GCloud fallback failed: ${fallbackErrorText}`);
462	                                continue;
463	                            }
464	                        } else {
465	                            lastError = new Error(`Gemini API ${response.status}: ${errorText}`);
466	                            continue;
467	                        }
468	                    } catch (fallbackErr) {
469	                        logger.error({ err: fallbackErr }, 'GCloud CLI not available or auth failed');
470	                        lastError = new Error(`Gemini API ${response.status}: ${errorText}`);
471	                        continue;
472	                    }
473	                }
474	
475	                const data = await response.json() as {
476	                    candidates?: Array<{
477	                        content?: { parts?: Array<{ text?: string }> };
478	                        finishReason?: string;
479	                    }>;
480	                    usageMetadata?: { totalTokenCount?: number };
481	                };
482	
483	                const text = data.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
484	                const latency = Date.now() - startTime;
485	
486	                logger.debug({ model: `gemini:${modelId}`, latency, tokens: data.usageMetadata?.totalTokenCount }, 'Secondary Cloud call complete');
487	
488	                return {
489	                    ok: true,
490	                    value: {
491	                        response: text,
492	                        tokensUsed: data.usageMetadata?.totalTokenCount,
493	                        metadata: {
494	                            model: `gemini:${modelId}`,
495	                            latency
496	                        }
497	                    }
498	                };
499	            } catch (err) {
500	                logger.error({ err, modelId }, 'Secondary Cloud network error for specific Gemini model');
501	                lastError = err as Error;
502	            }
503	        }
504	
505	        return { ok: false, error: lastError || new Error('All Gemini retry attempts failed.') };
506	    }
