508	    private async callOllama(params: ModelCallParams, startTime: number): Promise<Result<ModelResponse>> {
509	        const url = `${this.config.ollamaBaseUrl}/api/generate`;
510	
511	        const fullPrompt = params.systemPrompt
512	            ? `${params.systemPrompt}\n\n${params.prompt}`
513	            : params.prompt;
514	
515	        const body = {
516	            model: params.model,
517	            prompt: fullPrompt,
518	            stream: false,
519	            images: params.images, // Multimodal support
520	            format: params.format === 'text' ? undefined : (params.format === 'json' ? 'json' : (this.config.outputFormat === 'json' ? 'json' : undefined)),
521	            options: {
522	                temperature: params.temperature ?? this.config.temperature,
523	                top_p: this.config.topP,
524	                repeat_penalty: this.config.repeatPenalty,
525	                num_ctx: this.config.numCtx,
526	                stop: this.config.stopSequences,
527	                num_predict: params.maxTokens ?? 4096
528	            }
529	        };
530	
531	        try {
532	            const controller = new AbortController();
533	            const signal = params.signal || AbortSignal.timeout(86_400_000); // 24 hours
534	            const combinedSignal = AbortSignal.any([signal, controller.signal]);
535	
536	            const response = await undiciFetch(url, {
537	                method: 'POST',
538	                headers: { 'Content-Type': 'application/json' },
539	                body: JSON.stringify(body),
540	                // Massive local timeout: natively handled by Undici dispatcher
541	                dispatcher: this.customAgent,
542	                signal: combinedSignal
543	            } as any);
544	
545	            // LOGGING LOOP: The Persistence Heartbeat
546	
547	            const persistenceInterval = setInterval(() => {
548	                const elapsed = Math.floor((Date.now() - startTime) / 1000);
549	                const minutes = Math.floor(elapsed / 60);
550	                const seconds = elapsed % 60;
551	                logger.info({
552	                    model: params.model,
553	                    elapsed: `${minutes}m ${seconds}s`,
554	                    pulse: 'STILL_REASONING'
555	                }, 'Î“Â¥Ã¿ Neural Pulse: Deep substrate calculation actively thinking...');
556	            }, 30000); // Pulse every 30s instead of 60s
557	
558	            try {
559	                if (!response.ok) {
560	                    clearInterval(persistenceInterval);
561	                    const errorText = await response.text();
562	                    logger.error({ status: response.status, model: params.model }, 'Ollama API error');
563	
564	                    // Activate cooldown on 429 rate limit responses or 500 server errors
565	                    if (response.status === 429 || response.status === 500) {
566	                        logger.warn({ model: params.model, status: response.status }, 'Ollama substrate degraded Ã¢â‚¬â€ activating fallback');
567	                        this.router?.activateOllamaCooldown();
568	                    }
569	
570	                    return { ok: false, error: new Error(`Ollama ${response.status}: ${errorText}`) };
571	                }
572	
573	                const data = await response.json() as { response?: string; done?: boolean };
574	                clearInterval(persistenceInterval);
575	                const latency = Date.now() - startTime;
576	
