1117	        if (!apiKey) return { ok: false, error: new Error('SECONDARY_CLOUD_API_KEY not set') };
1118	
1119	        // Tiered Embedding Fallback Sequence
1120	        const primaryModel = this.config.geminiEmbeddingModel;
1121	        const fallbackSequence = [
1122	            primaryModel,
1123	            'text-embedding-004',
1124	            'models/text-embedding-004',
1125	            'gemini-embedding-001',
1126	            'models/embedding-001'
1127	        ];
1128	
1129	        const uniqueSequence = Array.from(new Set(fallbackSequence));
1130	        let lastError: Error | undefined;
1131	
1132	        for (const modelId of uniqueSequence) {
1133	            const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelId}:embedContent?key=${apiKey}`;
1134	
1135	            try {
1136	                const response = await undiciFetch(url, {
1137	                    method: 'POST',
