1139	                    body: JSON.stringify({ content: { parts: [{ text }] } }),
1140	                    signal: AbortSignal.timeout(this.getTimeoutByYaoState())
1141	                });
1142	
1143	                if (!response.ok) {
1144	                    const errorText = await response.text();
1145	                    if (response.status === 404) {
1146	                        logger.warn({ modelId }, 'Gemini embedding model not found (404), trying next...');
1147	                        lastError = new Error(`Gemini embed 404: ${modelId} - ${errorText}`);
1148	                        continue;
1149	                    }
1150	                    return { ok: false, error: new Error(`Gemini embed error ${response.status}: ${errorText}`) };
1151	                }
1152	
1153	                const data = await response.json() as { embedding?: { values?: number[] } };
1154	                const values = data.embedding?.values ?? [];
1155	                if (values.length === 0) {
1156	                    lastError = new Error(`Gemini embed ${modelId} returned empty values.`);
1157	                    continue;
1158	                }
1159	
1160	                logger.debug({ modelId }, 'Gemini embedding complete');
1161	                return { ok: true, value: new Float32Array(values) };
1162	            } catch (err) {
1163	                logger.error({ err, modelId }, 'Gemini embedding network failure');
1164	                lastError = err as Error;
1165	            }
1166	        }
1167	
1168	        return { ok: false, error: lastError || new Error('All Gemini embedding attempts failed.') };
1169	    }
