1171	    private async embedOllama(text: string, model: string): Promise<Result<Float32Array>> {
1172	        const url = `${this.config.ollamaBaseUrl}/api/embeddings`;
1173	
1174	        try {
1175	            const response = await undiciFetch(url, {
1176	                method: 'POST',
1177	                headers: { 'Content-Type': 'application/json' },
1178	                body: JSON.stringify({
1179	                    model,
1180	                    prompt: text,
1181	                    options: {
1182	                        num_ctx: this.config.numCtx,
1183	                        temperature: 0.0 // Embeddings should generally be completely deterministic
1184	                    }
1185	                }),
1186	                signal: AbortSignal.timeout(this.getTimeoutByYaoState())
1187	            });
1188	
1189	            if (!response.ok) {
1190	                return { ok: false, error: new Error(`Ollama embed error: ${response.status}`) };
1191	            }
1192	
1193	            const data = await response.json() as { embedding?: number[] };
1194	            const values = data.embedding ?? [];
1195	            return { ok: true, value: new Float32Array(values) };
1196	        } catch (err) {
1197	            return { ok: false, error: err as Error };
1198	        }
1199	    }
