1202	    public async healthCheck(): Promise<{ online: boolean; details: string }> {
1203	        const ollamaBase = this.config.ollamaBaseUrl || 'http://localhost:11434';
1204	        let ollamaOnline = false;
1205	        let modelCount = 0;
1206	        
1207	        for (let attempt = 1; attempt <= 3; attempt++) {
1208	            try {
1209	                const response = await undiciFetch(`${ollamaBase}/api/tags`, { signal: AbortSignal.timeout(15000) });
1210	                if (response.ok) {
1211	                    const data = await response.json() as { models?: any[] };
1212	                    modelCount = data.models?.length || 0;
1213	                    ollamaOnline = true;
1214	                    break;
1215	                }
1216	            } catch (e) {
1217	                if (attempt === 3) {
1218	                    ollamaOnline = false;
1219	                } else {
1220	                    await new Promise(res => setTimeout(res, 2000 * attempt));
1221	                }
1222	            }
1223	        }
1224	
1225	        const cloudKeys = [
1226	            { name: 'Gemini', key: this.config.secondaryCloudApiKey },
1227	            { name: 'HuggingFace', key: this.config.primaryCloudApiKey },
1228	            { name: 'Cloudflare', key: this.config.cloudflareApiToken }
1229	        ];
1230	        const activeCloud = cloudKeys.filter(k => !!k.key).map(k => k.name).join(', ');
1231	
1232	        return {
1233	            online: ollamaOnline, 
1234	            details: `ModelClient: ${ollamaOnline ? 'ONLINE' : 'DEGRADED'} (Local: ${modelCount} models | Cloud: ${activeCloud || 'None'})`
1235	        };
1236	    }
1237	}
