6	import { createLogger } from '../utils/logger.js';
7	
8	const logger = createLogger('OllamaCapabilityConfig');
9	
10	export interface OllamaCapability {
11	    readonly name: string;
12	    readonly preferredModel: string;
13	    readonly minCtx: number;
14	    readonly domain: 'reasoning' | 'code' | 'vision' | 'reflex' | 'embedding' | 'chat';
15	    readonly fallbackModels: readonly string[];
16	}
17	
18	const _registry = new Map<string, OllamaCapability>();
19	
20	function loadFromEnv(): void {
21	    const defs: Array<[string, OllamaCapability['domain'], string[]]> = [
22	        ['THINK', 'reasoning', ['deepseek-r1:8b']],
23	        ['CODE_HEAVY', 'code', ['deepseek-r1:32b', 'qwen2.5-coder:14b-instruct-q5_K_M', 'deepseek-r1:8b']],
24	        ['CODE_MID', 'code', ['gemma4:26b', 'qwen2.5-coder:7b-instruct-q4_K_M']],
25	        ['CODE_FAST', 'code', ['qwen2.5-coder:7b-instruct-q4_K_M', 'gemma4:26b']],
26	        ['FAST', 'reflex', ['gemma4:26b']],
27	        ['VISION', 'vision', ['moondream:latest', 'gemma4:26b']],
28	        ['EMBED', 'embedding', ['qwen3-embedding:latest', 'nomic-embed-text:latest']],
29	    ];
30	
31	    for (const [suffix, domain, fallbacks] of defs) {
32	        const model = process.env[`OLLAMA_MODEL_${suffix}`];
33	        const ctx = parseInt(process.env[`OLLAMA_CTX_${suffix}`] || '4096', 10);
34	        if (!model) continue;
35	        _registry.set(suffix.toLowerCase(), Object.freeze({
36	            name: suffix.toLowerCase(),
37	            preferredModel: model,
38	            minCtx: isNaN(ctx) ? 4096 : ctx,
39	            domain,
40	            fallbackModels: Object.freeze([model, ...fallbacks.filter(f => f !== model)])
41	        }));
42	    }
43	    logger.info({ count: _registry.size }, 'Ollama capability registry loaded');
44	}
45	
46	loadFromEnv();
47	
48	export const getCapability = (tier: string): Readonly<OllamaCapability> | null =>
49	    _registry.get(tier.toLowerCase()) || null;
50	
51	export const isCapabilityTier = (tier: string): boolean =>
52	    _registry.has(tier.toLowerCase());
