204	function loadEnvFile(envName: string = '.env'): void {
205	    const cwdEnv = join(process.cwd(), envName);
206	    
207	    // Calculate package root
208	    const thisDir = dirname(fileURLToPath(import.meta.url));
209	    const pkgEnv = join(thisDir, '..', '..', '..', envName);
210	
211	    const envPath = existsSync(cwdEnv) ? cwdEnv : (existsSync(pkgEnv) ? pkgEnv : null);
212	    
213	    if (!envPath) return;
214	    
215	    try {
216	        const content = readFileSync(envPath, 'utf8');
217	        for (const line of content.split('\n')) {
218	            const trimmed = line.trim();
219	            if (!trimmed || trimmed.startsWith('#')) continue;
220	            const match = trimmed.match(/^([^=]+)=(.*)$/);
221	            if (match) {
222	                const key = match[1].trim();
223	                const value = match[2].trim().replace(/^['"]|['"]$/g, ''); // Strip quotes
224	                process.env[key] = value;
225	            }
226	        }
227	    } catch {
228	        // Silently fail if `.env` exists but is unreadable
229	    }
230	}
