291	export function loadConfig(configPath: string): SovereignConfig {
292	    // 1. Force load user-specified environments to ensure API keys exist globally
293	    loadEnvFile('.env');
294	
295	    let fileConfig: Partial<SovereignConfig> = {};
296	    if (existsSync(configPath)) {
297	        try {
298	            fileConfig = JSON.parse(readFileSync(configPath, 'utf8'));
299	        } catch {
300	            // Silently fall back to defaults if JSON is malformed
301	        }
302	    }
303	
304	    const config: any = { ...DEFAULT_CONFIG, ...fileConfig };
305	
306	    // 2. Apply Environment Variable Overrides
307	    for (const [configKey, envKey] of Object.entries(ENV_VAR_MAP)) {
308	        const envVal = process.env[envKey];
309	        if (envVal !== undefined) {
310	            // Handle Type Conversion
311	            if (typeof (DEFAULT_CONFIG as any)[configKey] === 'number') {
312	                config[configKey] = Number(envVal);
313	            } else if (Array.isArray((DEFAULT_CONFIG as any)[configKey])) {
314	                try {
315	                    config[configKey] = JSON.parse(envVal);
316	                } catch {
317	                    // Maintain existing value if not valid JSON array
318	                }
319	            } else {
320	                config[configKey] = envVal;
321	            }
322	        }
323	    }
324	
325	    config.primaryCloudApiKey = process.env['PRIMARY_CLOUD_API_KEY'] ?? process.env['HUGGINGFACE_API_KEY'] ?? config.primaryCloudApiKey;
326	    config.secondaryCloudApiKey = process.env['SECONDARY_CLOUD_API_KEY'] ?? process.env['GOOGLE_API_KEY'] ?? config.secondaryCloudApiKey;
327	
328	    // Phase 105: Explicit YouTube Environment Mapping (Upstream Resilience)
329	    if (process.env['YOUTUBE_CLIENT_ID'] || process.env['YOUTUBE_CLIENT_SECRET'] || process.env['YOUTUBE_API_KEY'] || process.env['YOUTUBE_TOKEN_PATH']) {
330	        config.youtube = config.youtube || {};
331	        config.youtube.clientId = process.env['YOUTUBE_CLIENT_ID'] ?? config.youtube.clientId;
332	        config.youtube.clientSecret = process.env['YOUTUBE_CLIENT_SECRET'] ?? config.youtube.clientSecret;
333	        config.youtube.apiKey = process.env['YOUTUBE_API_KEY'] ?? config.youtube.apiKey;
334	        config.youtube.projectId = process.env['YOUTUBE_PROJECT_ID'] ?? config.youtube.projectId;
335	        config.youtube.channelId = process.env['YOUTUBE_CHANNEL_ID'] ?? config.youtube.channelId;
336	        config.youtube.youtubeId = process.env['YOUTUBE_YOUTUBE_ID'] ?? config.youtube.youtubeId;
337	        config.youtube.tokenPath = process.env['YOUTUBE_TOKEN_PATH'] ?? config.youtube.tokenPath;
338	    }
339	
340	    // Phase 106: Normalize wsPort defaults (Default to 8765 if -1 or missing)
341	    if (config.wsPort === -1 || config.wsPort === undefined) {
342	        config.wsPort = 8788;
343	    }
344	
345	    return config as SovereignConfig;
346	}
347	
348	export function getDefaultSovereignConfig(): SovereignConfig {
349	    return { ...DEFAULT_CONFIG };
350	}
